// Konfiguration + Warteschlange lesen, offene Units bis ~dailyMinutes akkumulieren.
// Grosse Units werden verlustfrei geschnitten (Rest als neue pending-Unit).
const cfg = ($("RTDB: config lesen").first() || {}).json || {};
const dailyMinutes = Number(cfg.dailyMinutes) || 30;
const targetWords = Number(cfg.targetWords) || 2800;
let queue = $json;
if (queue && typeof queue === "object" && queue.data && !queue.status && !queue.order) queue = queue.data;
if (!queue || typeof queue !== "object") queue = {};

const WPM = 200;
function wc(s){ return String(s == null ? "" : s).trim().split(/\s+/).filter(Boolean).length; }
const units = Object.keys(queue)
  .filter(function(k){ return queue[k] && typeof queue[k] === "object"; })
  .map(function(k){ return Object.assign({ _id: k }, queue[k]); });
const pending = units
  .filter(function(u){ return (u.status || "pending") === "pending"; })
  .sort(function(a,b){ return (Number(a.order)||0) - (Number(b.order)||0); });

const budget = dailyMinutes;
let acc = 0;
const combined = [];
const chosen = [];
const queueUpdate = {};
for (let i = 0; i < pending.length; i++) {
  const u = pending[i];
  const est = Number(u.estMinutes) || Math.max(1, Math.ceil(wc(u.content) / WPM));
  if (acc === 0 && est > budget) {
    const words = String(u.content || "").split(/\s+/);
    const takeN = Math.max(1, budget * WPM);
    const takeText = words.slice(0, takeN).join(" ");
    const restText = words.slice(takeN).join(" ");
    combined.push({ title: u.title, content: takeText });
    const consumed = Object.assign({}, u, { content: takeText, status: "split", estMinutes: Math.max(1, Math.ceil(wc(takeText)/WPM)) });
    delete consumed._id;
    queueUpdate[u._id] = consumed;
    if (restText.trim()) {
      const newId = "u_" + Date.now() + "_r" + i;
      queueUpdate[newId] = { sourceId: (u.sourceId || null), order: (Number(u.order)||0) + 0.5, title: (u.title || "Unit") + " (Fortsetzung)", content: restText, estMinutes: Math.max(1, Math.ceil(wc(restText)/WPM)), status: "pending" };
    }
    chosen.push(u._id); acc += budget; break;
  }
  if (acc > 0 && acc + est > budget) break;
  combined.push({ title: u.title, content: u.content });
  const delivered = Object.assign({}, u, { status: "delivered" });
  delete delivered._id;
  queueUpdate[u._id] = delivered;
  chosen.push(u._id); acc += est;
}

const dateKey = new Date().toLocaleDateString("en-CA", { timeZone: (cfg.timezone || "Europe/Zurich") });
const combinedText = combined.map(function(c){ return "## " + (c.title || "Unit") + "\n" + (c.content || ""); }).join("\n\n");
const system = "Du bist ein praeziser Lern-Autor. Aus dem gelieferten Lernstoff erstellst du (1) eine gut strukturierte Theorie als HTML-Fragment (theoryHtml: NUR Inhalts-Tags wie h2,h3,p,ul,ol,li,strong,em,code,blockquote,table — KEIN html/head/body/style/script/doctype), didaktisch aufbereitet, aber ohne Inhalt zu erfinden; und (2) 4-8 Verstaendnisfragen, die AUSSCHLIESSLICH aus dieser Theorie beantwortbar sind, jede mit einer knappen Musterantwort; und (3) 3-6 Flashcards (front/back). Deutsche Sprache, Schweizer Konvention (kein scharfes S). Antworte AUSSCHLIESSLICH mit einem JSON-Objekt, ohne Markdown-Fences, ohne Vor-/Nachtext: {\"theoryHtml\":\"...\",\"questions\":[{\"q\":\"...\",\"a\":\"...\"}],\"flashcards\":[{\"front\":\"...\",\"back\":\"...\"}]}";

return [{ json: { hasWork: combined.length > 0, dateKey: dateKey, combinedText: combinedText, unitIds: chosen, queueUpdate: queueUpdate, targetWords: targetWords, dailyMinutes: dailyMinutes, system: system } }];

// Canonical Smarter document-HTML builder.
// This exact logic goes into the n8n "Finalize / Build HTML" Code node.
// Self-contained (inline CSS, no external requests), print-friendly,
// Quantus-Design Schiefer/Leinen. Each question card carries data-qid="qN"
// so the Quantus app can dock an answer field under it.
function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
  });
}
function buildDocumentHtml(dateStr, theoryHtml, questions) {
  var qs = Array.isArray(questions) ? questions : [];
  var qCards = qs.map(function (q, i) {
    var qid = (q && q.id) ? q.id : ("q" + (i + 1));
    var text = (q && (q.q || q.question || q.frage)) || "";
    return '' +
      '<section class="q" data-qid="' + esc(qid) + '">' +
        '<div class="q-head"><span class="q-num">' + (i + 1) + '</span>' +
        '<h3 class="q-text">' + esc(text) + '</h3></div>' +
      '</section>';
  }).join("\n");

  return '' +
'<!doctype html>\n<html lang="de"><head><meta charset="utf-8">' +
'<meta name="viewport" content="width=device-width, initial-scale=1">' +
'<title>Smarter — ' + esc(dateStr) + '</title>\n<style>\n' +
'*{box-sizing:border-box}' +
'body{margin:0;background:#EFEAE1;color:#2B3134;font:16px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;padding:32px 20px}' +
